#!/usr/bin/env bash
# Print the Homebrew formula for a release tag.
# Usage: render-homebrew-formula.sh <tag> <dir with turtle-<target>.tar.gz.sha256 files> [owner/repo]
set -euo pipefail

tag=${1:?tag, for example v0.0.1}
sums=${2:?directory with the .sha256 files}
repo=${3:-EmVeeNL/turtle-flow}
version=${tag#v}

sum() {
  local file="$sums/turtle-$1.tar.gz.sha256"
  [[ -f $file ]] || { echo "missing $file" >&2; exit 1; }
  local value
  value=$(cut -d' ' -f1 "$file")
  [[ $value =~ ^[0-9a-f]{64}$ ]] || { echo "bad checksum in $file" >&2; exit 1; }
  printf '%s' "$value"
}

url() { printf 'https://github.com/%s/releases/download/%s/turtle-%s.tar.gz' "$repo" "$tag" "$1"; }

cat <<FORMULA
# Generated by .github/scripts/render-homebrew-formula.sh in $repo. Do not edit by hand.
require_relative "../custom_download_strategy"

class TurtleFlow < Formula
  desc "Local-first AI software factory CLI and dashboard"
  homepage "https://github.com/$repo"
  version "$version"
  license :cannot_represent

  on_macos do
    on_arm do
      url "$(url aarch64-apple-darwin)", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "$(sum aarch64-apple-darwin)"
    end
    on_intel do
      url "$(url x86_64-apple-darwin)", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "$(sum x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$(url aarch64-unknown-linux-gnu)", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "$(sum aarch64-unknown-linux-gnu)"
    end
    on_intel do
      url "$(url x86_64-unknown-linux-gnu)", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "$(sum x86_64-unknown-linux-gnu)"
    end
  end

  def install
    bin.install "turtle"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/turtle --version")
  end
end
FORMULA
